    34	        BookJpaEntity raw = loadBookPort.findRaw(command.bookId());
    35	        if (raw == null) {
    36	            throw new BookNotFoundException(command.bookId());
    37	        }
    38	        Book book = loadBookPort.loadBook(command.bookId())
    39	                .orElseThrow(() -> new BookNotFoundException(command.bookId()));
    40	        if (book.getStatus() == BookStatus.ON_LOAN) {
    41	            throw new BookAlreadyOnLoanException(book.getId());
    42	        }
    43	        Loan loan = Loan.start(book.getId(), command.memberId(), LocalDate.now());
    44	        book.setStatus(BookStatus.ON_LOAN);
    45	        saveBookPort.saveBook(book);
    46	        saveLoanPort.saveLoan(loan);
    47	        return loan;
    48	    }
    49	}
